create table t1(a, b, c);
create index t1a on t1(a);
create index t1bc on t1(b, c);
create unique index t1c on t1(c);
with recursive n(i) as (select 1 union all select i+1 from n where i < 500) insert into t1 select i % 7, i % 13, i from n;
create table t2(x primary key, y) without rowid;
insert into t2 select a || '-' || c, b from t1 where c <= 100;
create index t2y on t2(y);
create table t3(p, q);
create index t3p on t3(p) where p > 10;
insert into t3 values(1, 2), (20, 3), (30, 4);
create table t4(z);
insert into t4 values(1), (2);
analyze;
select tbl, idx, stat from sqlite_stat1 order by tbl, idx;
explain query plan select * from t1 where a = 3 and b = 5;
explain query plan select * from t1 where b = 5 and c > 10;
delete from t1 where a = 6;
analyze t1;
select tbl, idx, stat from sqlite_stat1 order by tbl, idx;
analyze t1bc;
select tbl, idx, stat from sqlite_stat1 order by tbl, idx;
analyze main;
pragma analysis_limit = 50;
analyze t1;
select tbl, idx, stat from sqlite_stat1 order by tbl, idx;
pragma analysis_limit = 0;
update sqlite_stat1 set stat = '1000 10 unordered' where idx = 't1a';
update sqlite_stat1 set stat = '1000 2 1 sz=40 noskipscan' where idx = 't1bc';
analyze sqlite_schema;
explain query plan select * from t1 where a = 3 and b = 5;
analyze nosuch;
explain analyze t4;
pragma optimize;
select tbl, idx, stat from sqlite_stat1 order by tbl, idx;
